int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_orphan *orphan, *prev_orphan = NULL;
    int ret = 0;

    if (!ext4_journal_tuned(sbi))
        return 0;

    mutex_lock(&sbi->s_orphan_lock);

    if (!ei->i_dentry)
        goto out;

    orphan = ei->i_dentry;

    while (orphan) {
        if (orphan->inum == inode->i_ino) {
            if (prev_orphan)
                prev_orphan->next = orphan->next;
            else
                sbi->s_last_orphan = orphan->next;

            ei->i_dentry = NULL;
            if (handle) {
                ret = ext4_journal_get_write_access(handle, sb, EXT4_JBD2_INODE(inode), 0);
                if (ret)
                    goto out;

                ret = ext4_mark_inode_dirty(handle, inode);
            }
            break;
        }
        prev_orphan = orphan;
        orphan = orphan->next;
    }

out:
    mutex_unlock(&sbi->s_orphan_lock);
    return ret;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_inode *orphan;
    int err = 0;

    if (!EXT4_JOURNAL(inode))
        return 0;

    lock_orphan_list(sbi);

    if (!ei->i_orphan) {
        unlock_orphan_list(sbi);
        return 0;
    }

    if (handle) {
        err = ext4_journal_get_write_access(handle, sbi->s_sbh, sbi->s_journal);
        if (err) {
            unlock_orphan_list(sbi);
            return err;
        }
    }

    if (sbi->s_orphans == ei->i_orphan) {
        sbi->s_orphans = ei->i_orphan->i_nexgentry;
        err = ext4_handle_dirty_super(handle, sb);
        if (err) {
            unlock_orphan_list(sbi);
            return err;
        }
    } else {
        struct ext4_inode *prev = sbi->s_orphans;
        while (prev && prev->i_nexgentry != ei->i_orphan)
            prev = prev->i_nexgentry;

        if (prev) {
            prev->i_nexgentry = ei->i_orphan->i_nexgentry;
            err = ext4_handle_dirty_inode(handle, sb, prev);
            if (err) {
                unlock_orphan_list(sbi);
                return err;
            }
        }
    }

    ei->i_orphan = NULL;
    mark_inode_dirty(inode);
    unlock_orphan_list(sbi);

    return err;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    int err = 0;
    struct ext4_iloc iloc;

    if (!EXT4_HAS_JOURNAL(sb))
        return 0;

    mutex_lock(&sbi->s_orphan_lock);

    if (ei->i_orphan_list_entry == NULL) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -EINVAL;
    }

    list_del(&ei->i_orphan_list_entry);

    if (handle) {
        err = ext4_journal_get_write_access(handle, inode->i_ino);
        if (err) {
            mutex_unlock(&sbi->s_orphan_lock);
            return err;
        }

        err = ext4_orphan_update(handle, inode);
        if (err) {
            mutex_unlock(&sbi->s_orphan_lock);
            return err;
        }
    }

    if (sbi->s_orphan_list == NULL)
        sbi->s_last_orphan = 0;
    else if (sbi->s_orphan_list == &ei->i_orphan_list_entry)
        sbi->s_last_orphan = ei->i_ino;

    mutex_unlock(&sbi->s_orphan_lock);

    mark_inode_dirty(inode);

    return err;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct super_block *sb = inode->i_sb;
    struct ext4_super_block *es = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_orphan *orphan;
    int err = 0;

    if (!ext4_journal_tuned(sb))
        return 0;

    mutex_lock(&EXT4_SB(sb)->s_orphan_mutex);

    if (!ei->i_dentry) {
        mutex_unlock(&EXT4_SB(sb)->s_orphan_mutex);
        return 0;
    }

    orphan = ei->i_dentry->d_fsdata;
    if (!orphan) {
        mutex_unlock(&EXT4_SB(sb)->s_orphan_mutex);
        return 0;
    }

    if (orphan->next) {
        struct ext4_orphan *next_orphan = orphan->next;
        next_orphan->prev = orphan->prev;
    }

    if (orphan->prev) {
        struct ext4_orphan *prev_orphan = orphan->prev;
        prev_orphan->next = orphan->next;
    } else {
        es->s_last_orphan = cpu_to_le32(le32_to_cpu(orphan->next));
        err = ext4_handle_dirty_metadata(handle, sb, es);
        if (err) {
            mutex_unlock(&EXT4_SB(sb)->s_orphan_mutex);
            return err;
        }
    }

    ei->i_dentry->d_fsdata = NULL;
    kfree(orphan);

    mutex_unlock(&EXT4_SB(sb)->s_orphan_mutex);
    return 0;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct super_block *sb = inode->i_sb;
    struct ext4_super_block *es = EXT4_SB(sb);
    int err = 0;

    if (!EXT4_HAS_JOURNAL(sb) || !EXT4_HANDLE_VALID(handle)) {
        return 0;
    }

    lock_orphan_list(sb);

    if (ei->i_orphan_list == NULL) {
        unlock_orphan_list(sb);
        return -EINVAL;
    }

    if (ei->i_orphan_list->i_ino != inode->i_ino) {
        struct inode *tmp_inode;
        struct inode *prev_inode = ei->i_orphan_list;

        list_for_each_entry(tmp_inode, &prev_inode->i_orphan_list, i_orphan) {
            if (tmp_inode == inode) {
                list_del(&inode->i_orphan);
                break;
            }
            prev_inode = tmp_inode;
        }

        if (tmp_inode != inode) {
            unlock_orphan_list(sb);
            return -EINVAL;
        }
    } else {
        list_del(&inode->i_orphan);
        es->s_last_orphan = 0;
    }

    if (handle) {
        err = ext4_journal_get_write_access(handle, inode->i_sb, ei->i_inode_table);
        if (err < 0) {
            unlock_orphan_list(sb);
            return err;
        }
        ext4_update_orphan_list_on_disk(sb);
        mark_inode_dirty(inode);
    }

    unlock_orphan_list(sb);
    return err;
}
